parameters.jsCode:
const brief = $node['Sisubriefi andmed'].json;

function allRows(nodeName) {
  try {
    return $items(nodeName).map(item => item.json).filter(row => Object.keys(row).length > 0);
  } catch (error) {
    return [];
  }
}

function textFromRows(rows, fallback) {
  if (!rows.length) return fallback;
  return rows.slice(0, 3).map((row, index) => {
    const values = Object.entries(row)
      .filter(([key, value]) => !key.startsWith('__') && value !== '' && value !== null && value !== undefined)
      .map(([key, value]) => `${key}: ${value}`)
      .join(', ');
    return `${index + 1}. ${values}`;
  }).join('\n');
}

const productsRows = allRows('Google Sheets - Products Get Rows');
const promotionRows = allRows('Google Sheets - Promotions Get Rows');
const segmentRows = allRows('Google Sheets - Segments Get Rows');

const brandVoice = {
  sihtrühm: 'teadlik moeklient Eesti linnades',
  toon: 'inspireeriv, praktiline, kvaliteeti rõhutav',
  sõnad: ['capsule wardrobe', 'jätkusuutlik', 'ajatu', 'mugav'],
  väldi: ['agressiivne allahindluse surve', 'liiga palju emoji\'sid'],
  piirang: 'ära väida, et toode on laos, kui laoinfot pole',
  cta: 'Vaata kevadkollektsiooni e-poes või külasta lähimat poodi'
};

return [
  {
    json: {
      ...brief,
      products_context: textFromRows(productsRows, 'Products sheet ei andnud valitud kategooriale ridu. Kasuta ainult vormi briefi ja ära mõtle tooteinfot välja.'),
      promotion_context: textFromRows(promotionRows, 'Promotions sheet ei andnud kampaaniale ridu. Ära luba allahindlust, tasuta tarnet ega muid kampaania väiteid.'),
      segment_context: textFromRows(segmentRows, 'Segments sheet ei andnud sihtrühmale ridu. Kasuta ainult vormi sihtrühma nime.'),
      brandVoice,
      sheets_lookup_status: {
        products_rows: productsRows.length,
        promotion_rows: promotionRows.length,
        segment_rows: segmentRows.length
      }
    }
  }
];

const data = $input.first().json;
const campaign = data['Kampaania nimi'] || 'Kampaania';
const channel = data.Kanal || 'Instagram';
const category = data.Tootekategooria || 'naiste riided';
const segment = data.Sihtrühm || 'UrbanStyle kliendid';
const tone = data.Toon || 'inspireeriv';
const message = data['Põhisõnum'] || '';

const title = `${campaign}: ${category} ${segment.toLowerCase()} jaoks`;
const body = `Avasta UrbanStyle'i ${category} valik, mis aitab luua ${message.toLowerCase()}. Toon: ${tone}. See on AI loodud mustand, mille turundustiim peab enne avaldamist üle vaatama.`;
const cta = channel === 'Email' ? 'Vaata kollektsiooni e-poes' : 'Tutvu kollektsiooniga ja vali oma kevadine lemmik';
const hashtags = '#UrbanStyle #JätkusuutlikMood #Kevadkollektsioon';

const draft = [
  `PEALKIRI: ${title}`,
  '',
  `TEKST: ${body}`,
  '',
  `CTA: ${cta}`,
  '',
  `HASHTAGID/SUBJECT: ${hashtags}`,
  '',
  'KVALITEEDIKONTROLL:',
  '- Kontrolli, kas kampaania ja tootekategooria on õiged.',
  '- Kontrolli, kas CTA sobib kanalile.',
  '- Kontrolli, et tekst ei luba valet laoseisu ega allahindlust.'
].join('\n');

const telegramChatId = 8234781531;
const telegramMessage = [
  'UrbanStyle N4 sisudraft',
  '',
  `Kampaania: ${campaign}`,
  `Kanal: ${channel}`,
  `Sihtrühm: ${segment}`,
  '',
  draft,
  '',
  'Tagasiside näide:',
  'PARANDA: tee lühemaks ja premium-tooniga'
].join('\n');

return [{ json: { ...data, draft, telegramChatId, telegramMessage } }];

const data = $input.first().json;
const message = data.message?.text || '';
const chatId = data.message?.chat?.id;
const feedback = message.replace(/^PARANDA:\s*/i, '').trim() || message;

const previousDraft = 'Näidis algne draft: Avasta UrbanStyle kevadkollektsioon ja leia oma uus lemmik. Vaata e-poodi juba täna! #UrbanStyle #Kevad';
const revised = [
  'PARANDATUD DRAFT',
  '',
  'Pealkiri: Kevadine garderoob, mis kestab kauem',
  '',
  `Paranduse suund: ${feedback}`,
  '',
  'Tekst: UrbanStyle kevadkollektsioon aitab valida ajatuid ja praktilisi lemmikuid, mida saad kanda rohkem kui ühe hooaja. Vaata valikut e-poes ja leia oma järgmine põhieseme lemmik.',
  '',
  'CTA: Vaata kevadkollektsiooni',
  '',
  'Kontroll: inimene peab enne avaldamist üle vaatama kampaania tingimused ja laoseisu.'
].join('\n');

return [{ json: { chatId, feedback, previousDraft, revised } }];
